\label{lema1} Let $f,$ $g:X\rightarrow \mathbb{R}_{\infty }$ be functions
such that $\limfunc{dom}f\cap \limfunc{dom}g\neq \emptyset $ and each one
has\ a continuous\ affine minorant. Then (\ref{equality}) is equivalent to 
\begin{equation}
(f+g)^{\ast }=\overline{f^{\ast }\square g^{\ast }}^{\tau }.  \label{no}
\end{equation}

f\ (\ref{equality})$\ $holds, then (\ref{clinf}) entails 
\begin{eqnarray*}
(f+g)^{\ast } &=&(\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g))^{\ast }=(( 
\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}}^{w^{\ast
\ast }}g))^{\ast } \\
&=&\overline{(\overline{\limfunc{co}}^{w^{\ast \ast }}f)^{\ast }\square ( 
\overline{\limfunc{co}}^{w^{\ast \ast }}g)^{\ast }}^{\tau }=\overline{ 
f^{\ast }\square g^{\ast }}^{\tau },
\end{eqnarray*} 
and (\ref{no}) follows. Conversely, observe that 
\begin{equation*}
\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)\geq \overline{\limfunc{co}} 
^{w^{\ast \ast }}(\overline{\limfunc{co}}^{w^{\ast \ast }}f+\overline{ 
\limfunc{co}}^{w^{\ast \ast }}g)=\left( \overline{\limfunc{co}}^{w^{\ast
\ast }}f\right) +\left( \overline{\limfunc{co}}^{w^{\ast \ast }}g\right)
>-\infty ,
\end{equation*} 
and $\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)\leq f+g$, so $\overline{ 
\limfunc{co}}^{w^{\ast \ast }}(f+g)$ is proper. Then, taking the conjugate
in\ (\ref{no}) and\ applying twice Moreau's theorem in $(X^{\ast },X^{\ast
\ast }),$ we obtain\ 
\begin{eqnarray*}
\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g) &=&(f+g)^{\ast \ast }=\left( 
\overline{f^{\ast }\square g^{\ast }}^{\tau }\right) ^{\ast } \\
&=&\left( f^{\ast }\square g^{\ast }\right) ^{\ast }=f^{\ast \ast }+g^{\ast
\ast }=(\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g).
\end{eqnarray*}

(i)$ If $f\in \Gamma _{0}(X),$ then $\partial _{\alpha }f(x)\neq \emptyset $
for all $\alpha >0.$

$(ii)$ If $f^{\ast }$\ is proper, then $f$ is also proper. Moreover, for
every $x\in \limfunc{dom}f$ and $x^{\ast }\in \limfunc{dom}f^{\ast }$, we
have $f^{\ast }(x^{\ast })+f(x)-\left\langle x^{\ast },x\right\rangle \geq
0. $ So, every scalar $\alpha $\ such that $\alpha >f^{\ast }(x^{\ast
})+f(x)-\left\langle x^{\ast },x\right\rangle $ satisfies $x^{\ast }\in
\partial _{\alpha }f(x),$ and we deduce $\varepsilon _{f}(x)\leq \alpha .$

$(iii)$ Since $\overline{\limfunc{co}}^{w^{\ast \ast }}f$ is proper, its
conjugate $f^{\ast }=(\overline{\limfunc{co}}^{w^{\ast \ast }}f)^{\ast }$ is
also proper\ (e.g., \cite[Proposition 3.1.4]{CHL23}). Take $x^{\ast }\in 
\limfunc{dom}f^{\ast }$ and pick any $\rho >0.$ Then there exists some\ $ 
x_{\rho }\in \limfunc{dom}f$ such that 
\begin{equation*}
f^{\ast }(x^{\ast })+f(x_{\rho })-\left\langle x^{\ast },x_{\rho
}\right\rangle \leq \rho ;
\end{equation*} 
that is, $x^{\ast }\in \partial _{\rho }f(x_{\rho })$ and 
\begin{equation*}
\inf_{z\in \limfunc{dom}f}\varepsilon _{f}(z)\leq \varepsilon _{f}(x_{\rho
})\leq \rho .
\end{equation*} 
Hence, $\inf_{z\in \limfunc{dom}f}\varepsilon _{f}(z)=0$ by\ the
arbitrariness of $\rho >0.$

he equivalence between $(i)$ and $(iii)$ is established in \cite[ 
Proposition 5.5]{CGH12}, and we prove next\ that $(i)\Longleftrightarrow
(ii) $,\ $(iv)\implies (i)$ and $(iii)\implies (iv).$

$(i)\implies (ii).$\ Assume that $(i)$ holds or, equivalently according to
Lemma \ref{lema1}, 
\begin{equation}
(f+g)^{\ast }=\overline{f^{\ast }\square g^{\ast }}^{\tau }.  \label{es}
\end{equation} 
Fix $x\in \limfunc{dom}f\cap \limfunc{dom}g$ and $\varepsilon >\varepsilon
_{f+g}(x)$ (remember that $\varepsilon _{f+g}(x)<\infty $ by Lemma \ref 
{lema2}$(ii)$). Take $x^{\ast }\in \partial _{\varepsilon }(f+g)(x)$ and a $ 
\theta $-neighborhood $U$ in $(X^{\ast },\tau ).$ Since $\varepsilon
>\varepsilon _{f+g}(x)$, there exists some $0<\alpha <\varepsilon $ such
that $\partial _{\alpha }(f+g)(x)\neq \emptyset ;$ that is, $\cup _{0<\delta
<\varepsilon }\partial _{\varepsilon -\delta }(f+g)(x)\neq \emptyset .$ So,
by applying \cite[Proposition 4.1.9]{CHL23} to the function $\hat{f}+\hat{g}$
defined on $X^{\ast \ast }$, we obtain 
\begin{eqnarray*}
x^{\ast } &\in &\partial _{\varepsilon }(f+g)(x)=\partial _{\varepsilon }( 
\hat{f}+\hat{g})(x) \\
&=&\limfunc{cl}\nolimits^{\tau }\left( \tbigcup_{0<\delta <\varepsilon
}\partial _{\varepsilon -\delta }(\hat{f}+\hat{g})(x)\right) =\limfunc{cl} 
\nolimits^{\tau }\left( \tbigcup_{0<\delta <\varepsilon }\partial
_{\varepsilon -\delta }(f+g)(x)\right) .
\end{eqnarray*} 
Hence, we find $\delta \in (0,\varepsilon )$ and $y^{\ast }\in \partial
_{\varepsilon -\delta }(f+g)(x)$ such that $x^{\ast }-y^{\ast }\in U.$
Moreover, since (remember (\ref{es})) 
\begin{eqnarray*}
(f+g)(x)+\overline{f^{\ast }\square g^{\ast }}^{\tau }(y^{\ast })
&=&(f+g)(x)+(f+g)^{\ast }(y^{\ast }) \\
&\leq &\left\langle y^{\ast },x\right\rangle +\varepsilon -\delta ,
\end{eqnarray*} 
we find some $z^{\ast }\in y^{\ast }+U$ such that 
\begin{equation*}
(f+g)(x)+\left( f^{\ast }\square g^{\ast }\right) (z^{\ast })\leq
\left\langle z^{\ast },x\right\rangle +\varepsilon -\delta /2<\left\langle
z^{\ast },x\right\rangle +\varepsilon .
\end{equation*} 
In other words, there are\ $z_{1}^{\ast },$ $z_{2}^{\ast }\in X^{\ast }$
such that $z_{1}^{\ast }+z_{2}^{\ast }=z^{\ast }$ and 
\begin{equation*}
(f+g)(x)+f^{\ast }(z_{1}^{\ast })+g^{\ast }(z_{2}^{\ast })\leq \left\langle
z_{1}^{\ast }+z_{2}^{\ast },x\right\rangle +\varepsilon ;
\end{equation*} 
that is, rearranging these terms, 
\begin{equation*}
(f(x)+f^{\ast }(z_{1}^{\ast })-\left\langle z_{1}^{\ast },x\right\rangle
)+(g(x)+g^{\ast }(z_{2}^{\ast })-\left\langle z_{2}^{\ast },x\right\rangle
)\leq \varepsilon .
\end{equation*} 
Now, we denote\ 
\begin{equation*}
\varepsilon _{1}:=f(x)+f^{\ast }(z_{1}^{\ast })-\left\langle z_{1}^{\ast
},x\right\rangle \text{ and }\varepsilon _{2}:=\varepsilon -\varepsilon _{1},
\end{equation*} 
so that $\varepsilon _{1}\geq 0$ and $\varepsilon _{2}\geq g(x)+g^{\ast
}(z_{2}^{\ast })-\left\langle z_{2}^{\ast },x\right\rangle \geq 0,$ and we
deduce that $\varepsilon _{1}+\varepsilon _{2}=\varepsilon ,$ $z_{1}^{\ast
}\in \partial _{\varepsilon _{1}}f(x)$ and $z_{2}^{\ast }\in \partial
_{\varepsilon _{2}}g(x).$ Thus,\ 
\begin{equation*}
x^{\ast }\in y^{\ast }+U\subset z^{\ast }+2U=z_{1}^{\ast }+z_{2}^{\ast
}+2U\subset \partial _{\varepsilon _{1}}f(x)+\partial _{\varepsilon
_{2}}g(x)+2U,
\end{equation*} 
and\ $(iii)$ follows by the arbitrariness of $U$.

$(ii)\implies (i).$ As observed in the proof of Lemma \ref{lema2}, remember\
that the function $\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)$ is proper
and, so, its conjugate $(f+g)^{\ast }$ is also proper. First, we are going
to prove that, for every given $x^{\ast }\in \limfunc{dom}(f+g)^{\ast },$ 
\begin{equation}
((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g))^{\ast }(x^{\ast })\leq (f+g)^{\ast }(x^{\ast }).
\label{des1}
\end{equation} 
Fix $\varepsilon >0$ and choose $x_{\varepsilon }\in X$ such that 
\begin{equation}
(f+g)^{\ast }(x^{\ast })+f(x_{\varepsilon })+g(x_{\varepsilon
})-\left\langle x^{\ast },x_{\varepsilon }\right\rangle <\varepsilon ;
\label{in1}
\end{equation} 
that is, $x^{\ast }\in \partial _{\varepsilon }(f+g)(x_{\varepsilon })$ and $ 
\varepsilon _{f+g}(x_{\varepsilon })<\varepsilon .$ So, by $(ii)$ we have\ 
\begin{equation}
x^{\ast }\in \limfunc{cl}\nolimits^{\tau }\left( \tbigcup_{\substack{  
\varepsilon _{1}+\varepsilon _{2}=\varepsilon  \\ \varepsilon
_{1},\varepsilon _{2}\geq 0}}\partial _{\varepsilon _{1}}f(x_{\varepsilon
})+\partial _{\varepsilon _{2}}g(x_{\varepsilon })\right) ,  \label{dos}
\end{equation} 
which reads, due to the inclusions $\partial _{\varepsilon
_{1}}f(x_{\varepsilon })\subset \partial _{\varepsilon _{1}}(\overline{ 
\limfunc{co}}^{w^{\ast \ast }}f)(x_{\varepsilon })$ and $\partial
_{\varepsilon _{2}}g(x_{\varepsilon })\subset \partial _{\varepsilon _{2}}( 
\overline{\limfunc{co}}^{w^{\ast \ast }}g)(x_{\varepsilon }),$ 
\begin{eqnarray}
x^{\ast } &\in &\limfunc{cl}\nolimits^{\tau }\left( \tbigcup_{\substack{  
\varepsilon _{1}+\varepsilon _{2}=\varepsilon  \\ \varepsilon
_{1},\varepsilon _{2}\geq 0}}\partial _{\varepsilon _{1}}(\overline{\limfunc{ 
co}}^{w^{\ast \ast }}f)(x_{\varepsilon })+\partial _{\varepsilon _{2}}( 
\overline{\limfunc{co}}^{w^{\ast \ast }}g)(x_{\varepsilon })\right)  \notag
\\
&\subset &\limfunc{cl}\nolimits^{\tau }(\partial _{\varepsilon }((\overline{ 
\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}}^{w^{\ast \ast
}}g))(x_{\varepsilon }))=\partial _{\varepsilon }((\overline{\limfunc{co}} 
^{w^{\ast \ast }}f)+(\overline{\limfunc{co}}^{w^{\ast \ast
}}g))(x_{\varepsilon });  \notag
\end{eqnarray} 
that is, 
\begin{equation}
((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g))^{\ast }(x^{\ast })+(\overline{\limfunc{co}}^{w^{\ast
\ast }}f)(x_{\varepsilon })+(\overline{\limfunc{co}}^{w^{\ast \ast
}}g)(x_{\varepsilon })-\left\langle x^{\ast },x_{\varepsilon }\right\rangle
\leq \varepsilon .  \label{inv}
\end{equation} 
At the same time, due to (\ref{dos}), the sets $\partial _{\varepsilon
_{1}}f(x_{\varepsilon })$ and $\partial _{\varepsilon _{2}}g(x_{\varepsilon
})$ are nonempty for some $\varepsilon _{1},\varepsilon _{2}\geq 0$ such
that $\varepsilon _{1}+\varepsilon _{2}=\varepsilon ,$ thus\ (e.g., \cite[ 
Exercise 62]{CHL23}) 
\begin{equation*}
(\overline{\limfunc{co}}^{w^{\ast \ast }}f)(x_{\varepsilon })\geq
f(x_{\varepsilon })-\varepsilon _{1},\text{ }(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g)(x_{\varepsilon })\geq g(x_{\varepsilon })-\varepsilon
_{2},
\end{equation*} 
and\ (\ref{in1}) and (\ref{inv}) entail 
\begin{multline*}
((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g))^{\ast }(x^{\ast })-(f+g)^{\ast }(x^{\ast }) \\
\leq ((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g))^{\ast }(x^{\ast })+f(x_{\varepsilon })+g(x_{\varepsilon
})-\left\langle x^{\ast },x_{\varepsilon }\right\rangle \\
\leq ((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}} 
^{w^{\ast \ast }}g))^{\ast }(x^{\ast })+(\overline{\limfunc{co}}^{w^{\ast
\ast }}f)(x_{\varepsilon })+(\overline{\limfunc{co}}^{w^{\ast \ast
}}g)(x_{\varepsilon })-\left\langle x^{\ast },x_{\varepsilon }\right\rangle
+\varepsilon \\
\leq 2\varepsilon .
\end{multline*} 
Hence, (\ref{des1}) follows by the arbitrariness of $\varepsilon $.
Moreover, since\ the\ inequality $((\overline{\limfunc{co}}^{w^{\ast \ast
}}f)+(\overline{\limfunc{co}}^{w^{\ast \ast }}g))^{\ast }\geq (f+g)^{\ast }$
always holds, we deduce that $((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+( 
\overline{\limfunc{co}}^{w^{\ast \ast }}g))^{\ast }=(f+g)^{\ast }$.
Therefore $(i)$ follows by applying Moreau's theorem to the last equality in
the pair $(X^{\ast },X^{\ast \ast }).$

$(iii)\implies (iv).$ For any\ $x\in X$ and $\varepsilon >0,$ $(iii)$
implies that 
\begin{equation}
\partial _{\varepsilon }(f+g)(x)\subset \limfunc{cl}\nolimits^{\tau
}(\partial _{2\varepsilon }f(x)+\partial _{2\varepsilon }g(x)),
\label{est0v}
\end{equation} 
which is $(iv).$

$(iv)\implies (i).$ Fix $x\in X$ and $\varepsilon >0.$ Since $\partial
_{2\varepsilon }f(x)\subset \partial _{2\varepsilon }(\overline{\limfunc{co}} 
^{w^{\ast \ast }}f)(x)$ and $\partial _{2\varepsilon }g(x)\subset \partial
_{2\varepsilon }(\overline{\limfunc{co}}^{w^{\ast \ast }}g)(x),$ $(iv)$
entails 
\begin{eqnarray*}
\partial _{\varepsilon }(f+g)(x) &\subset &\limfunc{cl}\nolimits^{\tau
}(\partial _{2\varepsilon }(\overline{\limfunc{co}}^{w^{\ast \ast
}}f)(x)+\partial _{2\varepsilon }(\overline{\limfunc{co}}^{w^{\ast \ast
}}g)(x)) \\
&\subset &\limfunc{cl}\nolimits^{\tau }(\partial _{4\varepsilon }((\overline{ 
\limfunc{co}}^{w^{\ast \ast }}f)+(\overline{\limfunc{co}}^{w^{\ast \ast
}}g))(x)) \\
&=&\partial _{4\varepsilon }((\overline{\limfunc{co}}^{w^{\ast \ast }}f)+( 
\overline{\limfunc{co}}^{w^{\ast \ast }}g))(x).
\end{eqnarray*} 
Now, since $(f+g)^{\ast }=(\overline{\limfunc{co}}^{w^{\ast \ast
}}(f+g))^{\ast }$ is proper, by applying \cite[Corollary 3.3 (see, also,
Remark 3.2(i))]{CGH18} in $X^{\ast \ast }$ (see, also, \cite{CHP17, CHS16,
LoVo14}) we deduce that 
\begin{equation}
\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)=\overline{\limfunc{co}} 
^{w^{\ast \ast }}(\hat{f}+\hat{g})=(\overline{\limfunc{co}}^{w^{\ast \ast
}}f)+(\overline{\limfunc{co}}^{w^{\ast \ast }}g)+c,  \label{est}
\end{equation} 
for some constant $c\in \mathbb{R}$. It is clear that $c\geq 0$ and let us
check that $c=0.$ Since $\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)$ is
proper, according to Lemma \ref{lema2}$(iii),$ for every $\varepsilon >0$
there exists some $x_{\varepsilon }\in X$ such that $\varepsilon
_{f+g}(x_{\varepsilon })<\varepsilon ;$ that is, $\partial _{\varepsilon
}(f+g)(x_{\varepsilon })\neq \emptyset .$ Thus, by (\ref{est0v}), the sets $ 
\partial _{2\varepsilon }f(x_{\varepsilon })$ and $\partial _{2\varepsilon
}g(x)$ are nonempty, and so\ 
\begin{equation*}
(\overline{\limfunc{co}}^{w^{\ast \ast }}f)(x_{\varepsilon })\geq
f(x_{\varepsilon })-2\varepsilon ,\text{ }(\overline{\limfunc{co}}^{w^{\ast
\ast }}g)(x_{\varepsilon })\geq g(x_{\varepsilon })-2\varepsilon .
\end{equation*} 
Thus,\ (\ref{est}) reads\ 
\begin{eqnarray*}
c &=&\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)(x_{\varepsilon })-( 
\overline{\limfunc{co}}^{w^{\ast \ast }}f)(x_{\varepsilon })-(\overline{ 
\limfunc{co}}^{w^{\ast \ast }}g)(x_{\varepsilon }) \\
&\leq &\overline{\limfunc{co}}^{w^{\ast \ast }}(f+g)(x_{\varepsilon
})-f(x_{\varepsilon })-g(x_{\varepsilon })+4\varepsilon \leq 4\varepsilon ,
\end{eqnarray*} 
and taking $\varepsilon \downarrow 0$ we conclude that\ $c=0.$

\label{lembb} Assume that\ $X$ is Banach. If $f\in \Gamma _{0}(X),$ then\
for all $z\in X^{\ast \ast }$\ we have that 
\begin{equation}
\partial \bar{f}^{w^{\ast \ast }}(z)=\tbigcap_{U\in \mathcal{N}}~\limfunc{cl} 
\nolimits^{\left\Vert \cdot \right\Vert _{\ast }}\left( \tbigcup_{x\in
z+U}\partial f(x)\right) ,  \label{mm}
\end{equation} 
where $\left\Vert \cdot \right\Vert _{\ast }$ is the dual norm in $X^{\ast }$
and $\mathcal{N}:=\mathcal{N}_{X^{\ast \ast }}(w^{\ast \ast }).$

ick\ $z\in X^{\ast \ast },$ $x^{\ast }\in \partial \bar{f}^{w^{\ast \ast
}}(z),$ $U\in z+\mathcal{N}$ , and choose $\varepsilon >0$ and $V\in z+ 
\mathcal{N}$ such that $V+\sqrt{\varepsilon }B_{X}\subset U.$\ Then 
\begin{equation*}
\bar{f}^{w^{\ast \ast }}(z)+f^{\ast }(x^{\ast })=\bar{f}^{w^{\ast \ast
}}(z)+(\bar{f}^{w^{\ast \ast }})^{\ast }(x^{\ast })\leq \left\langle
z,x^{\ast }\right\rangle <\left\langle z,x^{\ast }\right\rangle +\varepsilon
,
\end{equation*} 
and, so, there exists some $x_{\varepsilon }\in V$ such that\ 
\begin{equation*}
f(x_{\varepsilon })+f^{\ast }(x^{\ast })<\left\langle x_{\varepsilon
},x^{\ast }\right\rangle +\varepsilon .
\end{equation*} 
Hence, $x^{\ast }\in \partial _{\varepsilon }f(x_{\varepsilon })$ and the
Brondsted-Rockafellar theorem (see, e.g., \cite[Proposition 4.3.7]{CHL23})
gives some $z_{\varepsilon }\in x_{\varepsilon }+\sqrt{\varepsilon }B_{X}$\
and $z_{\varepsilon }^{\ast }\in x^{\ast }+\sqrt{\varepsilon }B_{X^{\ast }}$
such $z_{\varepsilon }^{\ast }\in \partial f(z_{\varepsilon }).$ Thus, $ 
z_{\varepsilon }\in V+\sqrt{\varepsilon }B_{X}\subset U$ and 
\begin{equation*}
x^{\ast }\in z_{\varepsilon }^{\ast }+\sqrt{\varepsilon }B_{X^{\ast
}}\subset \partial f(z_{\varepsilon })+\sqrt{\varepsilon }B_{X^{\ast
}}\subset \tbigcup_{x\in U}\partial f(x)+\sqrt{\varepsilon }B_{X^{\ast }}.
\end{equation*} 
By the arbitrariness of $\varepsilon $ we deduce that $x^{\ast }\in \limfunc{ 
cl}^{\left\Vert \cdot \right\Vert _{\ast }}\left( \cup _{x\in U}\partial
f(x)\right) $ and the arbitrariness of $U$ yields the inclusion
\textquotedblleft $\subset $\textquotedblright\ in (\ref{mm}).

Conversely, if $x^{\ast }$ is in\ the right hand side of (\ref{mm}),$\ $then
for each $U\in \mathcal{N}$ and $\varepsilon >0$ there exist some $x\in z+U$
and $z^{\ast }\in \partial f(x)$ such that $\left\Vert x^{\ast }-z^{\ast
}\right\Vert _{\ast }\leq \varepsilon $ and $f^{\ast }(x^{\ast })\leq
f^{\ast }(z^{\ast })+\varepsilon ,$ due to the $\left\Vert \cdot \right\Vert
_{\ast }$-lower semicontinuity of $f^{\ast }.\ $Hence, 
\begin{eqnarray*}
\inf_{y\in U}f(z+y)+f^{\ast }(x^{\ast }) &\leq &f(x)+f^{\ast }(x^{\ast }) \\
&\leq &f(x)+f^{\ast }(z^{\ast })+\varepsilon \\
&=&\left\langle x,z^{\ast }\right\rangle +\varepsilon \leq \left\langle
x,x^{\ast }\right\rangle +\left\Vert x\right\Vert \varepsilon +\varepsilon ,
\end{eqnarray*} 
and, by taking the supremum over $U$, 
\begin{equation*}
\bar{f}^{w^{\ast \ast }}(z)+(\bar{f}^{w^{\ast \ast }})^{\ast }(x^{\ast
})=\sup_{U}\inf_{y\in z+U}f(y)+f^{\ast }(x^{\ast })\leq \left\langle
x,x^{\ast }\right\rangle +\left\Vert x\right\Vert \varepsilon +\varepsilon .
\end{equation*} 
Thus, as $\varepsilon \downarrow 0$ we obtain that\ $x^{\ast }\in \partial
f^{w^{\ast \ast }}(z).$

\label{thmseq}Assume that $X$ is Banach, and let $f,$ $g\in \Gamma _{0}(X)$
such that $\limfunc{dom}f\cap \limfunc{dom}g\neq \emptyset .$ Then the
following statements are equivalent, provided that $\tau $ is the dual norm\
topology (see (\ref{tau})):

$(v)$ $\overline{f+g}^{w^{\ast \ast }}=\overline{f}^{w^{\ast \ast }}+ 
\overline{g}^{w^{\ast \ast }}.$

$(vi)$ For all $x\in X$ and $x^{\ast }\in \partial (f+g)(x)$, there are
sequences $x_{n},$ $y_{n}\rightarrow x$\ and $x_{n}^{\ast }\in \partial
f(x_{n}),$ $y_{n}^{\ast }\in \partial g(y_{n})$ such that 
\begin{equation*}
\left\langle x_{n}^{\ast },x_{n}-x\right\rangle \rightarrow 0,\text{ } 
\left\langle y_{n}^{\ast },y_{n}-x\right\rangle \rightarrow 0,\text{ } 
f(x_{n})\rightarrow f(x),\text{ }g(y_{n})\rightarrow g(x),
\end{equation*} 
and 
\begin{equation*}
x_{n}^{\ast }+y_{n}^{\ast }\overset{\left\Vert \cdot \right\Vert _{\ast }}{ 
\rightarrow }x^{\ast }.
\end{equation*}

(vi)\implies (v):$ Given\ $x\in X$ and $x^{\ast }\in \partial (f+g)(x),$ we
let the sequences $(x_{n}),$ $(y_{n})\subset X$, $x_{n}^{\ast }\in \partial
f(x_{n})$ and $y_{n}^{\ast }\in \partial g(y_{n})$ be as\ in $(vi).$\ Then,
given any $\varepsilon >0,$ for all $n$ large enough\ we have 
\begin{equation*}
x^{\ast }\in x_{n}^{\ast }+y_{n}^{\ast }+\varepsilon B_{X^{\ast }},\text{ } 
\left\langle x_{n}^{\ast },x_{n}-x\right\rangle \leq \varepsilon /2,\text{ } 
f(x)-f(x_{n})\leq \varepsilon /2,\text{ }
\end{equation*} 
\begin{equation*}
\left\langle y_{n}^{\ast },y_{n}-y\right\rangle \leq \varepsilon /2,\text{
and }g(x)-g(y_{n})\leq \varepsilon /2.
\end{equation*} 
Hence, for any $y\in \limfunc{dom}f$, 
\begin{eqnarray*}
\left\langle x_{n}^{\ast },y-x\right\rangle &=&\left\langle x_{n}^{\ast
},y-x_{n}\right\rangle +\left\langle x_{n}^{\ast },x_{n}-x\right\rangle \\
&\leq &f(y)-f(x_{n})+\varepsilon /2\leq f(y)-f(x)+\varepsilon ,
\end{eqnarray*} 
and we deduce\ that $x_{n}^{\ast }\in \partial _{\varepsilon }f(x).$
Similarly, $y_{n}^{\ast }\in \partial _{\varepsilon }g(x)\ $and, so, 
\begin{equation*}
x^{\ast }\in \partial _{\varepsilon }f(x)+\partial _{\varepsilon
}g(x)+\varepsilon B_{X^{\ast }},
\end{equation*} 
entailing\ 
\begin{equation*}
x^{\ast }\in \partial _{\varepsilon }\overline{f}^{w^{\ast \ast
}}(x)+\partial _{\varepsilon }\overline{g}^{w^{\ast \ast }}(x)+\varepsilon
B_{X^{\ast }}\subset \partial _{2\varepsilon }\left( \overline{f}^{w^{\ast
\ast }}+\overline{g}^{w^{\ast \ast }}\right) (x)+\varepsilon B_{X^{\ast }}.
\end{equation*} 
Thus, for each\ $\delta >0$, 
\begin{equation*}
\partial (f+g)(x)\subset \partial _{\delta }\left( \overline{f}^{w^{\ast
\ast }}+\overline{g}^{w^{\ast \ast }}\right) (x)+\varepsilon B_{X^{\ast }}, 
\text{ for all }\varepsilon \in (0,\delta /2),
\end{equation*} 
and we obtain\ 
\begin{eqnarray*}
\partial (f+g)(x) &\subset &\tbigcap_{0<\varepsilon <\delta /2}\left(
\partial _{\delta }\left( \overline{f}^{w^{\ast \ast }}+\overline{g} 
^{w^{\ast \ast }}\right) (x)+\varepsilon B_{X^{\ast }}\right) \\
&=&\limfunc{cl}\nolimits^{\left\Vert \cdot \right\Vert _{\ast }}\left(
\partial _{\delta }\left( \overline{f}^{w^{\ast \ast }}+\overline{g} 
^{w^{\ast \ast }}\right) (x)\right) =\partial _{\delta }\left( \overline{f} 
^{w^{\ast \ast }}+\overline{g}^{w^{\ast \ast }}\right) (x),
\end{eqnarray*} 
implying 
\begin{equation*}
\partial (f+g)(x)\subset \tbigcap_{\delta >0}\partial _{\delta }\left( 
\overline{f}^{w^{\ast \ast }}+\overline{g}^{w^{\ast \ast }}\right)
(x)=\partial \left( \overline{f}^{w^{\ast \ast }}+\overline{g}^{w^{\ast \ast
}}\right) (x).
\end{equation*} 
Now, applying\ Lemma \ref{lembb} successively to $f+g$ and $\overline{f} 
^{w^{\ast \ast }}+\overline{g}^{w^{\ast \ast }}$, we conclude that, for all $ 
z\in X^{\ast \ast },$ 
\begin{eqnarray*}
\partial (\overline{f+g}^{w^{\ast \ast }})(z) &=&\tbigcap_{U\in \mathcal{N}}~ 
\limfunc{cl}\nolimits^{\left\Vert \cdot \right\Vert _{\ast }}\left(
\tbigcup_{x\in z+U}\partial (f+g)(x)\right) \\
&\subset &\tbigcap_{U\in \mathcal{N}}~\limfunc{cl}\nolimits^{\left\Vert
\cdot \right\Vert _{\ast }}\left( \tbigcup_{x\in z+U}\partial \left( 
\overline{f}^{w^{\ast \ast }}+\overline{g}^{w^{\ast \ast }}\right) (x)\right)
\\
