\label{qualif}Let $f,$ $g:X\rightarrow \mathbb{R}_{\infty }$ be convex
functions with continuous\ affine minorants. If $f$ is continuous somewhere
in $\limfunc{dom}g$, then, for all $x\in X^{\ast \ast }$ and $\varepsilon
\geq 0,$\ 
\begin{eqnarray}
\partial _{\varepsilon }\left( \overline{f+g}^{w^{\ast \ast }}\right) (x)
&=&\partial _{\varepsilon }\left( \bar{f}^{w^{\ast \ast }}+\bar{g}^{w^{\ast
\ast }}\right) (x)  \notag \\
&=&\bigcup\limits_{\substack{ \varepsilon _{1},\varepsilon _{2}\geq 0  \\  
\varepsilon _{1}+\varepsilon _{2}=\varepsilon }}\left( \partial
_{\varepsilon _{1}}\bar{f}^{w^{\ast \ast }}(x)+\partial _{\varepsilon _{2}} 
\bar{g}^{w^{\ast \ast }}(x)\right) .  \label{dd}
\end{eqnarray}

he first equality is an immediate consequence of Corollary \ref{corqualif}.
To prove the second one we observe first that $\overline{f}^{w^{\ast \ast
}}, $ $\overline{g}^{w^{\ast \ast }}\in \Gamma _{0}(X^{\ast \ast }),$ due to
existence of continuous affine minorants for\ $f$ and $g$ in $X.$ Then,
thanks to Theorem \ref{prop1}, the functions $\overline{f}^{w^{\ast \ast }}$
and $\overline{g}^{w^{\ast \ast }}$ satisfy (\ref{sum1b});\ i.e., for all $ 
x\in X^{\ast \ast }$ and $\varepsilon \geq 0,$ 
\begin{equation}
\partial _{\varepsilon }\left( \overline{f}^{w^{\ast \ast }}+\overline{g} 
^{w^{\ast \ast }}\right) (x)=\tbigcap_{\alpha >\varepsilon }\limfunc{cl} 
\nolimits^{\tau }\left( A_{\alpha }\right) ,  \label{mas}
\end{equation} 
where 
\begin{equation*}
A_{\alpha }:=\bigcup\limits_{\substack{ \varepsilon _{1},\varepsilon
_{2}\geq 0  \\ \varepsilon _{1}+\varepsilon _{2}=\alpha }}\left( \partial
_{\varepsilon _{1}}\overline{f}^{w^{\ast \ast }}(x)+\partial _{\varepsilon
_{2}}\overline{g}^{w^{\ast \ast }}(x)\right) .
\end{equation*} 
Take $x^{\ast }\in \partial _{\varepsilon }\left( \overline{f}^{w^{\ast \ast
}}+\overline{g}^{w^{\ast \ast }}\right) (x)\ $and consider any net $(\alpha
_{V})_{V\in \mathcal{N}}\subset ]0,1[$ such that $\alpha _{V}\downarrow
\varepsilon $ (here, $\mathcal{N}:=\mathcal{N}_{X^{\ast }}(\tau )$ is
partially-ordered by descending inclusions). Hence, for all $V\in \mathcal{N} 
,$ (\ref{mas}) implies that $x^{\ast }\in \limfunc{cl}\nolimits^{\tau
}\left( A_{\alpha _{V}}\right) $ and we can find $x_{V}^{\ast }\in A_{\alpha
_{V}}$ such that $x_{V}^{\ast }\in x^{\ast }+V.$ Given any\ $W\in \mathcal{N} 
,$ by taking\ $V_{0}=W$ we see that 
\begin{equation*}
x_{V}^{\ast }\in x^{\ast }+V\subset x^{\ast }+W,\text{ for all }V\subset
V_{0};
\end{equation*} 
that is, $(x_{V}^{\ast })$ is $\tau $-convergent to $x^{\ast }.$ Moreover,
for each $V\in \mathcal{N}$ there are $\varepsilon _{V,1},$ $\varepsilon
_{V,2}\geq 0,$ $y_{V}^{\ast }\in \partial _{\varepsilon _{V,1}}\overline{f} 
^{w^{\ast \ast }}(x)$ and $z_{V}^{\ast }\in \partial _{\varepsilon _{V,2}} 
\overline{g}^{w^{\ast \ast }}(x)$ such that $\varepsilon _{V,1}+\varepsilon
_{V,2}=\alpha _{V}$ and $x_{V}^{\ast }=y_{V}^{\ast }+z_{V}^{\ast }.$ By the
current continuity hypothesis, we choose $x_{0}\in \limfunc{dom}g$ and $ 
\theta $-neighborhood $U_{0}\subset X$ such that 
\begin{equation*}
\overline{f}^{w^{\ast \ast }}(x_{0}+u)\leq f(x_{0}+u)\leq f(x_{0})+1,\text{
for all }u\in U_{0}.
\end{equation*} 
Then, for all $u\in U_{0}$ ($\subset X$), 
\begin{eqnarray}
\left\langle y_{V}^{\ast },x_{0}-x+u\right\rangle &\leq &\overline{f} 
^{w^{\ast \ast }}(x_{0}+u)-\overline{f}^{w^{\ast \ast }}(x)+\varepsilon
_{V,1}  \notag \\
&\leq &f(x_{0})-\overline{f}^{w^{\ast \ast }}(x)+2.  \label{hamd}
\end{eqnarray} 
At the same time, there exists some $M\geq 0$ such that 
\begin{equation*}
\left\langle y_{V}^{\ast },x_{0}-x\right\rangle \geq -M,\text{ for all }V;
\end{equation*} 
otherwise, since $\left\langle x_{V}^{\ast },x_{0}-x\right\rangle
=\left\langle y_{V}^{\ast }+z_{V}^{\ast },x_{0}-x\right\rangle $ converges
to $\left\langle x^{\ast },x_{0}-x\right\rangle $ and $z_{V}^{\ast }\in
\partial _{\varepsilon _{V,2}}\overline{g}^{w^{\ast \ast }}(x),$ we get a
contradiction with 
\begin{equation*}
\left\langle z_{V}^{\ast },x_{0}-x\right\rangle \leq \overline{g}^{w^{\ast
\ast }}(x_{0})-\overline{g}^{w^{\ast \ast }}(x)+1,\text{ for all }V.
\end{equation*} 
Therefore (\ref{hamd}) reads\ 
\begin{equation*}
\left\langle y_{V}^{\ast },u\right\rangle \leq f(x_{0})-\overline{f} 
^{w^{\ast \ast }}(x)+M+2,\text{ for all }u\in U_{0},
\end{equation*} 
and,\ thanks to the Alaoglu-Bourbaki theorem, we may assume that $ 
(y_{V}^{\ast })_{V}$ is $\sigma (X^{\ast },X)$-convergent to some $y^{\ast
}\in X^{\ast };$ hence, $(z_{V}^{\ast })_{V}$ is $\sigma (X^{\ast },X)$ 
-convergent to $x^{\ast }-y^{\ast }.$ We can also assume that $\varepsilon
_{V,1}\downarrow \varepsilon _{1}$ and $\varepsilon _{V,2}\downarrow
\varepsilon _{2}$ with $\varepsilon _{1}+\varepsilon _{2}=\varepsilon .$
More precisely, since for all $y\in X$ and\ $V\in \mathcal{N}$ we have 
\begin{equation*}
\left\langle y_{V}^{\ast },y-x\right\rangle \leq \overline{f}^{w^{\ast \ast
}}(y)-\overline{f}^{w^{\ast \ast }}(x)+\varepsilon _{V,1}\leq f(y)-\overline{ 
f}^{w^{\ast \ast }}(x)+\varepsilon _{V,1},
\end{equation*} 
by taking the limit on $V$ we infer that 
\begin{equation*}
\left\langle y^{\ast },y-x\right\rangle \leq f(y)-\overline{f}^{w^{\ast \ast
}}(x)+\varepsilon _{1}.
\end{equation*} 
Thus, knowing that $X$ is $\sigma (X^{\ast \ast },X^{\ast })$-dense in $ 
X^{\ast \ast },$ we deduce that 
\begin{equation*}
\left\langle y^{\ast },y-x\right\rangle \leq \overline{f}^{w^{\ast \ast
}}(y)-\overline{f}^{w^{\ast \ast }}(x)+\varepsilon _{1},\text{ for all }y\in
X^{\ast \ast };
\end{equation*} 
that is, $y^{\ast }\in \partial _{\varepsilon _{1}}\overline{f}^{w^{\ast
\ast }}(x).$ Similarly, we show that $x^{\ast }-y^{\ast }\in \partial
_{\varepsilon _{2}}\overline{g}^{w^{\ast \ast }}(x)$, and we conclude that 
\begin{equation*}
x^{\ast }=y^{\ast }+(x^{\ast }-y^{\ast })\in \partial _{\varepsilon _{1}} 
\overline{f}^{w^{\ast \ast }}(x)+\partial _{\varepsilon _{2}}\overline{g} 
^{w^{\ast \ast }}(x).
\end{equation*} 
Thus, we are done because the inclusion \textquotedblleft $\supset $ 
\textquotedblright\ in (\ref{dd}) is straightforward.

(i)$ Assume that $f$ is continuous at $x_{0}\in \limfunc{dom}f.$ Given $ 
x\in X$, we introduce the functions $\varphi ,$ $\psi \in \Gamma _{0}( 
\mathbb{R})$ defined as 
\begin{equation*}
\varphi (s):=f(x_{0}+s(x-x_{0})),\text{ }\psi (s):=g(x_{0}+s(x-x_{0}),\text{ 
}s\in \mathbb{R}.
\end{equation*} 
Since\ $0\in \limfunc{int}(\limfunc{dom}\psi ),$ \cite[Lemma 4.4.2]{CHL23}
entails 
\begin{equation*}
\varphi (s)-\psi (s)=f(x_{0})-g(x_{0})=:c_{0},\text{ for all }s\in \mathbb{R} 
,
\end{equation*} 
which in turn implies $f(x)=g(x)+c_{0}.$

